public static class Employee {
    private final Long id;
    private final String firstName;
    private final String lastName;
    private final double salary;
    // konstruktor + gettery
}

public record EmployeeDto(Long id, String fullName, double salary) {}

@Mapper
public interface EmployeeMapper {
    @Mapping(target = "fullName",
            expression = "java(employee.getFirstName() + \" \" + employee.getLastName())")
    EmployeeDto toDto(Employee employee);

    List<EmployeeDto> toDtoList(List<Employee> employees);
}

// Uzycie:
EmployeeMapper mapper = Mappers.getMapper(EmployeeMapper.class);
EmployeeDto dto = mapper.toDto(new Employee(1L, "Anna", "Kowalska", 8500.0));
// dto.fullName() == "Anna Kowalska", id i salary zmapowane automatycznie
